/**
 * Header behaviour and mobile navigation.
 *
 * Three jobs:
 *   1. Resolve the transparent hero header into a solid bar on scroll.
 *   2. Flip the header to light-on-dark whenever a section marked
 *      data-nav="dark" is passing beneath it.
 *   3. Run the mobile overlay, including focus trapping and scroll lock.
 */
(function () {
  'use strict';
  var header = document.querySelector('[data-rc-header]');
  if (!header) { return; }
  var SOLID_AT = 80;
  var ticking = false;
  function syncSolid() {
    header.classList.toggle('is-solid', window.scrollY > SOLID_AT);
    ticking = false;
  }
  function onScroll() {
    if (!ticking) {
      ticking = true;
      window.requestAnimationFrame(syncSolid);
    }
  }
  if (header.classList.contains('rc-header--over-hero')) {
    window.addEventListener('scroll', onScroll, { passive: true });
    syncSolid();
  }
  /* --- 2. Dark-section detection -----------------------------------------
     A 1px observation band sits at the vertical centre of the header.
     Any dark section intersecting that band owns the header's colour. */
  var darkSections = document.querySelectorAll('[data-nav="dark"]');
  if (darkSections.length && 'IntersectionObserver' in window) {
    var active = new Set();
    var themeObserver = null;
    /*
     * rootMargin must be a valid length. In a prerendered page (speculation
     * rules), a background tab or some in-app browsers, innerHeight can be
     * 0 at this point, which used to produce "--1px" and throw, killing the
     * whole script. Round and clamp, and rebuild the band on resize.
     */
    var buildThemeObserver = function () {
      var band = Math.max(0, Math.round(header.offsetHeight / 2));
      var below = Math.max(0, Math.round((window.innerHeight || document.documentElement.clientHeight || 0) - band - 1));
      if (themeObserver) { themeObserver.disconnect(); }
      active.clear();
      try {
        themeObserver = new IntersectionObserver(
          function (entries) {
            entries.forEach(function (entry) {
              if (entry.isIntersecting) {
                active.add(entry.target);
              } else {
                active.delete(entry.target);
              }
            });
            header.classList.toggle('is-dark', active.size > 0);
          },
          { rootMargin: '-' + band + 'px 0px -' + below + 'px 0px' }
        );
      } catch (e) {
        themeObserver = null;
        return;
      }
      darkSections.forEach(function (section) { themeObserver.observe(section); });
    };
    buildThemeObserver();
    var resizeTimer = null;
    var lastHeight = window.innerHeight;
    window.addEventListener('resize', function () {
      // Mobile browsers fire resize when the URL bar slides; only rebuild
      // on a meaningful change.
      if (Math.abs(window.innerHeight - lastHeight) < 80) { return; }
      lastHeight = window.innerHeight;
      window.clearTimeout(resizeTimer);
      resizeTimer = window.setTimeout(buildThemeObserver, 150);
    }, { passive: true });
    // A page prerendered at zero height is rebuilt when it is shown.
    document.addEventListener('visibilitychange', function () {
      if (!document.hidden && window.innerHeight !== lastHeight) {
        lastHeight = window.innerHeight;
        buildThemeObserver();
      }
    });
  }
  /* --- 3. Mobile overlay -------------------------------------------------- */
  var burger = document.querySelector('[data-rc-burger]');
  var overlay = document.querySelector('[data-rc-overlay]');
  if (!burger || !overlay) { return; }
  var FOCUSABLE = 'a[href], button:not([disabled]), input, textarea, select, [tabindex]:not([tabindex="-1"])';
  var lastFocused = null;
  function openNav() {
    lastFocused = document.activeElement;
    overlay.hidden = false;
    // Force a reflow so the transition runs from the closed state.
    void overlay.offsetHeight;
    overlay.classList.add('is-open');
    burger.setAttribute('aria-expanded', 'true');
    document.body.classList.add('rc-scroll-locked');
    var first = overlay.querySelector(FOCUSABLE);
    if (first) { first.focus(); }
    document.addEventListener('keydown', onKeydown);
  }
  function closeNav() {
    overlay.classList.remove('is-open');
    burger.setAttribute('aria-expanded', 'false');
    document.body.classList.remove('rc-scroll-locked');
    document.removeEventListener('keydown', onKeydown);
    if (lastFocused) { lastFocused.focus(); }
    // Keep it out of the accessibility tree once the transition ends.
    window.setTimeout(function () {
      if (!overlay.classList.contains('is-open')) { overlay.hidden = true; }
    }, 700);
  }
  function onKeydown(event) {
    if (event.key === 'Escape') {
      closeNav();
      return;
    }
    if (event.key !== 'Tab') { return; }
    var items = Array.prototype.slice.call(overlay.querySelectorAll(FOCUSABLE));
    if (!items.length) { return; }
    var first = items[0];
    var last = items[items.length - 1];
    if (event.shiftKey && document.activeElement === first) {
      event.preventDefault();
      last.focus();
    } else if (!event.shiftKey && document.activeElement === last) {
      event.preventDefault();
      first.focus();
    }
  }
  burger.addEventListener('click', function () {
    if (overlay.classList.contains('is-open')) { closeNav(); } else { openNav(); }
  });
  overlay.addEventListener('click', function (event) {
    if (event.target.closest('a')) { closeNav(); }
  });
  // A resize into the desktop layout must not leave the overlay latched open.
  window.addEventListener('resize', function () {
    if (window.innerWidth >= 992 && overlay.classList.contains('is-open')) { closeNav(); }
  });
})();

;
(function () {
  'use strict';
  var reduced = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
  var targets = document.querySelectorAll('.rc-reveal, .rc-line');
  var hero = document.querySelector('.rc-hero');
  function revealAll() {
    Array.prototype.forEach.call(targets, function (el) { el.classList.add('is-revealed'); });
    if (hero) { hero.classList.add('is-ready'); }
  }
  if (reduced || !('IntersectionObserver' in window)) {
    revealAll();
    return;
  }
  if (hero) {
    var heroImage = hero.querySelector('img');
    var startHero = function () {
      hero.classList.add('is-ready');
      Array.prototype.forEach.call(
        hero.querySelectorAll('.rc-reveal, .rc-line'),
        function (el) { el.classList.add('is-revealed'); }
      );
    };
    if (!heroImage || heroImage.complete) {
      window.requestAnimationFrame(startHero);
    } else {
      heroImage.addEventListener('load', startHero, { once: true });
      heroImage.addEventListener('error', startHero, { once: true });
      window.setTimeout(startHero, 1200);
    }
  }
  function shouldReveal(entry) {
    return entry.isIntersecting || entry.boundingClientRect.top < 0;
  }
  var observer = new IntersectionObserver(
    function (entries, obs) {
      entries.forEach(function (entry) {
        if (!shouldReveal(entry)) { return; }
        entry.target.classList.add('is-revealed');
        obs.unobserve(entry.target);
      });
    },
    { threshold: 0.15, rootMargin: '0px 0px -10% 0px' }
  );
  Array.prototype.forEach.call(targets, function (el) {
    if (hero && hero.contains(el)) { return; }
    observer.observe(el);
  });
  var sweepTimer = null;
  function sweep() {
    var stranded = document.querySelectorAll('.rc-reveal:not(.is-revealed), .rc-line:not(.is-revealed)');
    Array.prototype.forEach.call(stranded, function (el) {
      if (el.getBoundingClientRect().top < window.innerHeight) {
        el.classList.add('is-revealed');
        observer.unobserve(el);
      }
    });
    if (!stranded.length) {
      window.removeEventListener('scroll', onScrollSweep);
    }
  }
  function onScrollSweep() {
    window.clearTimeout(sweepTimer);
    sweepTimer = window.setTimeout(sweep, 150);
  }
  window.addEventListener('scroll', onScrollSweep, { passive: true });
  window.addEventListener('load', sweep);
  var cue = document.querySelector('.rc-hero__cue');
  if (cue) {
    window.addEventListener(
      'scroll',
      function () { cue.classList.toggle('is-hidden', window.scrollY > 80); },
      { passive: true }
    );
  }
})();

;
(function () {
  'use strict';
  var hero = document.querySelector('[data-rc-hero]');
  if (!hero) { return; }
  var slides = Array.prototype.slice.call(hero.querySelectorAll('[data-rc-slide]'));
  var taglines = Array.prototype.slice.call(hero.querySelectorAll('[data-rc-tagline]'));
  var bars = Array.prototype.slice.call(hero.querySelectorAll('[data-rc-goto]'));
  var toggle = hero.querySelector('[data-rc-hero-toggle]');
  var controls = hero.querySelector('[data-rc-hero-controls]');
  if (slides.length < 2) {
    if (controls) { controls.hidden = true; }
    return;
  }
  var reduced = window.matchMedia('(prefers-reduced-motion: reduce)');
  var HOLD = 6500;
  var LEAVE = 520;
  var HANDOFF = 420;
  var current = 0;
  var timer = null;
  var handoff = null;
  var paused = false;
  function resetBar(bar, seen) {
    var fill = bar.querySelector('.rc-hero__bar-fill');
    if (!fill) { return; }
    fill.style.transition = 'none';
    fill.style.inlineSize = seen ? '100%' : '0%';
    void fill.offsetWidth;
  }
  function runBar(bar) {
    var fill = bar.querySelector('.rc-hero__bar-fill');
    if (!fill) { return; }
    resetBar(bar, false);
    fill.style.transition = 'inline-size ' + HOLD + 'ms linear';
    fill.style.inlineSize = '100%';
  }
  function paintBars() {
    bars.forEach(function (bar, i) {
      bar.classList.toggle('is-active', i === current);
      if (i === current) {
        bar.setAttribute('aria-current', 'true');
      } else {
        bar.removeAttribute('aria-current');
      }
      if (i < current) {
        bar.classList.add('is-seen');
        resetBar(bar, true);
      } else if (i > current) {
        bar.classList.remove('is-seen');
        resetBar(bar, false);
      }
    });
    if (!paused && !reduced.matches) {
      runBar(bars[current]);
    } else {
      resetBar(bars[current], false);
    }
  }
  function settle() {
    taglines.forEach(function (tagline, i) {
      tagline.classList.remove('is-leaving');
      if (i === current) {
        tagline.classList.add('is-active');
        tagline.removeAttribute('aria-hidden');
      } else {
        tagline.classList.remove('is-active');
        tagline.setAttribute('aria-hidden', 'true');
      }
    });
  }
  function show(next) {
    if (next === current) { return; }
    if (handoff) {
      window.clearTimeout(handoff);
      handoff = null;
      settle();
    }
    var from = taglines[current];
    slides[current].classList.remove('is-active');
    slides[next].classList.add('is-active');
    from.classList.remove('is-active');
    from.classList.add('is-leaving');
    from.setAttribute('aria-hidden', 'true');
    current = next;
    paintBars();
    handoff = window.setTimeout(function () {
      handoff = null;
      settle();
    }, HANDOFF);
  }
  function advance() {
    show((current + 1) % slides.length);
  }
  function start() {
    if (reduced.matches || paused) { return; }
    stop();
    timer = window.setInterval(advance, HOLD);
    paintBars();
  }
  function stop() {
    if (timer) {
      window.clearInterval(timer);
      timer = null;
    }
  }
  if (HANDOFF < LEAVE * 0.8) { HANDOFF = Math.round(LEAVE * 0.8); }
  function setPaused(value) {
    paused = value;
    if (toggle) {
      toggle.setAttribute('aria-pressed', paused ? 'true' : 'false');
      var label = toggle.querySelector('.rc-hero__toggle-text');
      if (label) { label.textContent = paused ? 'Play' : 'Pause'; }
    }
    if (paused) {
      stop();
      resetBar(bars[current], false);
    } else {
      start();
    }
  }
  if (toggle) {
    toggle.addEventListener('click', function () { setPaused(!paused); });
  }
  bars.forEach(function (bar, i) {
    bar.addEventListener('click', function () {
      show(i);
      if (!paused) { start(); }
    });
  });
  document.addEventListener('visibilitychange', function () {
    if (document.hidden) { stop(); } else if (!paused) { start(); }
  });
  var onPreferenceChange = function () {
    if (reduced.matches) {
      stop();
      resetBar(bars[current], false);
    } else {
      start();
    }
  };
  if (typeof reduced.addEventListener === 'function') {
    reduced.addEventListener('change', onPreferenceChange);
  }
  if (reduced.matches) {
    if (controls) {
      paintBars();
    }
    return;
  }
  window.setTimeout(start, 1200);
})();

;
(function () {
  'use strict';
  var counters = document.querySelectorAll('[data-rc-count]');
  if (!counters.length) { return; }
  var reduced = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
  if (reduced || !('IntersectionObserver' in window)) { return; }
  var DURATION = 1400;
  function ease(t) {
    return t === 1 ? 1 : 1 - Math.pow(2, -10 * t);
  }
  function run(el) {
    var target = parseInt(el.getAttribute('data-rc-count'), 10);
    if (isNaN(target)) { return; }
    var prefix = el.getAttribute('data-rc-prefix') || '';
    var suffix = el.getAttribute('data-rc-suffix') || '';
    var started = null;
    function step(now) {
      if (started === null) { started = now; }
      var progress = Math.min((now - started) / DURATION, 1);
      el.textContent = prefix + Math.round(ease(progress) * target) + suffix;
      if (progress < 1) { window.requestAnimationFrame(step); }
    }
    window.requestAnimationFrame(step);
  }
  var observer = new IntersectionObserver(
    function (entries, obs) {
      entries.forEach(function (entry) {
        if (!entry.isIntersecting) { return; }
        run(entry.target);
        obs.unobserve(entry.target);
      });
    },
    { threshold: 0.6 }
  );
  Array.prototype.forEach.call(counters, function (el) { observer.observe(el); });
})();

;
(function () {
  'use strict';
  var groups = document.querySelectorAll('[data-rc-process]');
  if (!groups.length) { return; }
  var reduced = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
  if (reduced || !('IntersectionObserver' in window)) {
    Array.prototype.forEach.call(groups, function (group) {
      Array.prototype.forEach.call(
        group.querySelectorAll('.rc-step'),
        function (step) { step.classList.add('is-active'); }
      );
      var fill = group.querySelector('.rc-progress__fill');
      if (fill) { fill.style.height = '100%'; }
    });
    return;
  }
  Array.prototype.forEach.call(groups, function (group) {
    var steps = Array.prototype.slice.call(group.querySelectorAll('.rc-step'));
    var fill = group.querySelector('.rc-progress__fill');
    if (!steps.length) { return; }
    var reached = 0;
    function paint() {
      steps.forEach(function (step, i) {
        step.classList.toggle('is-active', i < reached);
      });
      if (fill) {
        fill.style.height = (reached / steps.length) * 100 + '%';
      }
    }
    var observer = new IntersectionObserver(
      function (entries) {
        entries.forEach(function (entry) {
          var index = steps.indexOf(entry.target) + 1;
          var passed = entry.isIntersecting || entry.boundingClientRect.top < 0;
          if (passed && index > reached) {
            reached = index;
            paint();
          }
        });
      },
      { threshold: 0, rootMargin: '0px 0px -33% 0px' }
    );
    steps.forEach(function (step) { observer.observe(step); });
  });
})();
